import{mkdirSync,readFileSync,writeFileSync,copyFileSync,readdirSync}from'node:fs';import{createHash}from'node:crypto';
mkdirSync('public',{recursive:true});
for(const f of['styles.css','v2.css','core.js','words.js','app-v2.js','hadith-v2.js','media-v2.js','account.js','sw.js','passages-1.js','passages-2.js','passages-3.js'])copyFileSync(f,'public/'+f);
const host=process.env.VERCEL_PROJECT_PRODUCTION_URL||process.env.VERCEL_URL||'localhost:8765';if(!/^[a-zA-Z0-9.-]+(?::\d+)?$/.test(host))throw Error('Invalid deployment host');
writeFileSync('public/index.html',readFileSync('index.html','utf8').replaceAll('__SITE__',host.startsWith('localhost')?'http://'+host:'https://'+host));
const config={supabaseUrl:process.env.PUBLIC_SUPABASE_URL||'',publishableKey:process.env.PUBLIC_SUPABASE_PUBLISHABLE_KEY||'',googleEnabled:process.env.PUBLIC_GOOGLE_SIGN_IN==='true'};
if(config.publishableKey.startsWith('sb_secret_'))throw Error('Never publish a secret Supabase key');if(config.publishableKey.split('.').length===3){const claims=JSON.parse(Buffer.from(config.publishableKey.split('.')[1],'base64url').toString());if(claims.role==='service_role')throw Error('Never publish service_role keys');}
writeFileSync('public/config.js','window.FQ_CONFIG='+JSON.stringify(config)+';');writeFileSync('public/manifest.webmanifest',JSON.stringify({id:'/',name:"Famous Qur'an",short_name:'Famous Quran',start_url:'/',scope:'/',display:'standalone',background_color:'#07130f',theme_color:'#07130f',icons:[{src:'/icon-192.png',sizes:'192x192',type:'image/png'},{src:'/icon-512.png',sizes:'512x512',type:'image/png',purpose:'any maskable'}]}));
await import('./brand.mjs');const hash=createHash('sha256');for(const f of readdirSync('public').sort())if(f!=='release.json')hash.update(f).update(readFileSync('public/'+f));const revision=hash.digest('hex').slice(0,16);writeFileSync('public/sw.js',readFileSync('public/sw.js','utf8').replaceAll('__REVISION__',revision));
const {verify}=await import('./verify.mjs');const checks=await verify();writeFileSync('public/release.json',JSON.stringify({version:'2.0.0',revision,commit:process.env.VERCEL_GIT_COMMIT_SHA||'local',builtAt:new Date().toISOString(),checks,cloudAuthConfigured:!!(config.supabaseUrl&&config.publishableKey)}));console.log('Famous Quran v2: '+checks.length+' static/worker checks passed. Cloud auth '+(config.supabaseUrl?'configured':'not configured'));
